std::vector<uint8_t> read_mario_rom() {
    std::ifstream in(MARIO_ROM_PATH, std::ios::binary);
    REQUIRE(in.good());
    return std::vector<uint8_t>(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

constexpr uint32_t kBootFrames = 120;

// the rows main.c tints and prints to, per games/mario/src/mario.h
constexpr uint32_t kTitleRow = 6;
constexpr uint32_t kPromptRow = 11;
constexpr uint32_t kPauseRow = 4;

// gbdk's ibm font lands ascii 0x20-0x7f on tiles 0x00-0x5f; space (tile 0) is excluded so a
// span only ever measures real glyphs
constexpr uint8_t kFontFirstTile = 0x00;
constexpr uint8_t kFontLastTile = 0x5F;

void run(gb::Gameboy& gameboy, uint32_t frames) {
    for (uint32_t i = 0; i < frames; ++i) {
        gameboy.run_frame();
    }
}

// leftmost and rightmost bg cell columns on a tile row whose id is in [lo, hi]
std::pair<int, int> glyph_span(const gb::Gameboy& gameboy, uint32_t row, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    int left = -1;
    int right = -1;
    for (uint32_t cx = 0; cx < 20; ++cx) {
        const uint16_t id = ids[(row * 8 + 3) * gb::kLcdWidth + cx * 8 + 3];
        if ((id & 0x100u) != 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(id);
        if (tile >= lo && tile <= hi) {
            if (left < 0) {
                left = static_cast<int>(cx);
            }
            right = static_cast<int>(cx);
        }
    }
    return {left, right};
}

// a 5-bit channel that is not the same as the other two makes the color read as non-gray
bool is_non_gray(uint16_t rgb555) {
    const uint16_t r = rgb555 & 0x1Fu;
    const uint16_t g = (rgb555 >> 5) & 0x1Fu;
    const uint16_t b = (rgb555 >> 10) & 0x1Fu;
    return !(r == g && g == b);
}

void press(gb::Gameboy& gameboy, gb::Button button, uint32_t frames) {
    gameboy.set_button(button, true);
    run(gameboy, frames);
    gameboy.set_button(button, false);
}

// boots, then presses b to enter the m2 debug camera, per games/mario/src/main.c's state machine
// (start enters play; select is the play camera's look-ahead now, so the debug state moved to b).
// terrain_init()'s ring fill (16 columns, each a banked read plus two vram writes) runs synchronously
// while the lcd is off; the host's run_frame() approximates real time in whole-frame budgets, so a
// display-off burst this size can outrun a single call and needs a few frames to fully drain before
// per-frame button timing (as goto_xy relies on) is trustworthy again
void enter_camera(gb::Gameboy& gameboy) {
    run(gameboy, kBootFrames);
    press(gameboy, gb::Button::B, 2);
    run(gameboy, 64);
}

// m19's front end sits between the title and a level: start opens SELECT FILE, start again opens
// file 1 onto the world map, and start a third time enters the node mario is standing on, which on
// a fresh file is 1-1. every one of those three is an lcd-off repaint that outruns a whole host
// frame, and the rom only samples the pad at the top of its loop - so each press has to wait for
// the burst before it, or the edge lands while nothing is reading. this is the player's own path
// in, so the forty-odd tests that use it exercise both new screens on every run
constexpr uint32_t kScreenSettleFrames = 60;

void step_screen(gb::Gameboy& gameboy, gb::Button button) {
    run(gameboy, kScreenSettleFrames);
    press(gameboy, button, 2);
}

// m19's world map, kMapSkyRgb in mario.h: the overworld sky lifted a shade so this one probe tells
// the map apart from the two overworld levels that share every other color with it. it is declared
// up here because leaving the map is what every entry into a level now waits on
// the map's rebuilt top/bottom bands are near-black (kMapSkyRgb in mario.h) rather than the old
// placeholder's sky blue - a host probe still needs the eyedropper to land on it
constexpr int kSkyMap = 1 | (1 << 5) | (1 << 10);
int sky_color(const gb::Gameboy& gameboy);

// mario is drawn on the map too, so "he is on screen" cannot say a level has loaded: what does is
// the backdrop no longer being the map's
void wait_off_map(gb::Gameboy& gameboy) {
    for (int i = 0; i < 400 && sky_color(gameboy) == kSkyMap; ++i) {
        gameboy.run_frame();
    }
}

// m20: a is the only confirm on the front end - start is "back" there now, so that esc (which the
// sdl frontend maps to start) walks the screens backwards the way the player asked for. start off
// the title is the exception: there is nothing behind it to go back to
void enter_play(gb::Gameboy& gameboy) {
    run(gameboy, kBootFrames);
    press(gameboy, gb::Button::Start, 2);
    step_screen(gameboy, gb::Button::A);
    step_screen(gameboy, gb::Button::A);
    wait_off_map(gameboy);
    run(gameboy, 64);
}

// select from the title starts the same level with the denser lab roster (kEnemyLab in mario.h)
void enter_lab(gb::Gameboy& gameboy) {
    run(gameboy, kBootFrames);
    press(gameboy, gb::Button::Select, 2);
    run(gameboy, 64);
}

