constexpr uint16_t max_world_x(const HostLevel& lv) {
    const int px = lv.columns * kBlockPx;
    return px > kScreenWidthPx ? static_cast<uint16_t>(px - kScreenWidthPx) : uint16_t{0};
}

constexpr uint16_t kMaxWorldX = max_world_x(kHostLevels[kLevel11]);

// tracks the rom's camera position by driving it exactly as main.c does: 2px per frame, one d-pad
// direction per axis, clamped the same way terrain.c clamps. the test never reads rom-private state.
struct Camera {
    uint16_t x = 0;
    uint8_t y = 0;

    void goto_xy(gb::Gameboy& gameboy, uint16_t target_x, uint8_t target_y) {
        while (x != target_x || y != target_y) {
            const bool right = x < target_x;
            const bool left = x > target_x;
            const bool down = y < target_y;
            const bool up = y > target_y;
            gameboy.set_button(gb::Button::Right, right);
            gameboy.set_button(gb::Button::Left, left);
            gameboy.set_button(gb::Button::Down, down);
            gameboy.set_button(gb::Button::Up, up);
            gameboy.run_frame();
            if (right) {
                x = static_cast<uint16_t>(x + 2);
            }
            if (left) {
                x = static_cast<uint16_t>(x - 2);
            }
            if (down) {
                y = static_cast<uint8_t>(y + 2);
            }
            if (up) {
                y = static_cast<uint8_t>(y - 2);
            }
        }
        gameboy.set_button(gb::Button::Right, false);
        gameboy.set_button(gb::Button::Left, false);
        gameboy.set_button(gb::Button::Down, false);
        gameboy.set_button(gb::Button::Up, false);
    }
};

// scy that brings block row `row` fully into the 144px window (see terrain.c's viewport math)
uint8_t scy_for_row(uint8_t row) {
    const uint16_t px = static_cast<uint16_t>(static_cast<uint16_t>(row) * kBlockPx);
    return static_cast<uint8_t>(px < kScyMax ? px : kScyMax);
}

// scx that brings block column `column` fully into the 160px window, clamped to the level's range
uint16_t scx_for_column(uint16_t column) {
    const uint16_t px = static_cast<uint16_t>(column * kBlockPx);
    return px < kMaxWorldX ? px : kMaxWorldX;
}

// the tile id at the world block (column, row)'s top-left 8x8 cell, given the camera sits at
// (cam_x, cam_y); the caller must have parked the camera so the block is actually on screen
uint8_t block_tile(const gb::Gameboy& gameboy, uint16_t column, uint8_t row, uint16_t cam_x, uint8_t cam_y) {
    const uint32_t screen_x = static_cast<uint32_t>(column) * kBlockPx - cam_x;
    const uint32_t screen_y = static_cast<uint32_t>(row) * kBlockPx - cam_y;
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const uint16_t id = ids[(screen_y + 3) * gb::kLcdWidth + screen_x + 3];
    return static_cast<uint8_t>(id & 0xFFu);
}

// pinned bg tile family ranges per claude-docs/milestones/18-smbd.md's test/tile-id contract and
// the id map recorded in games/mario/src/mario.h. m18's art pass gave most blocks four distinct
// quadrants, so the background outgrew the 0xa0-0xbf block and now also uses the eight ids past
// mario's last sprite frame plus a scenery run borrowed from the font's glyph range. every entry
// here names the family of the block's TOP-LEFT tile, which is the one block_tile() samples
bool tile_in_kind_family(uint8_t tile, uint8_t kind) {
    switch (kind) {
    case kBlockEmpty:
        return tile == 0x00;
    case kBlockGround:
        return tile >= 0xA0 && tile <= 0xA1;
    case kBlockGroundFill:
        return tile >= 0xA2 && tile <= 0xA3;
    case kBlockHard:
    case kBlockStair:
        return tile >= 0xFA && tile <= 0xFD;
    case kBlockBrick:
        return tile >= 0xA4 && tile <= 0xA7;
    case kBlockQuestion:
        return tile >= 0xA8 && tile <= 0xAB;
    case kBlockPipeTl:
    case kBlockPipeTr:
    case kBlockPipeBodyL:
    case kBlockPipeBodyR:
        return tile >= 0xB0 && tile <= 0xB8;
    case kBlockFlagPole:
        return tile == 0xB9;
    case kBlockFlagBall:
        return tile == 0x30;
    case kBlockFlagCloth:
        return tile >= 0x31 && tile <= 0x34;
    case kBlockCastle:
        return tile == 0x22;
    case kBlockCastleCrenel:
        return tile == 0x23;
    case kBlockCastleCrenelInner:
        return tile == 0x5B;
    case kBlockCastleWindow:
        return tile >= 0x24 && tile <= 0x27;
    case kBlockCastleDoorTop:
        return tile >= 0x28 && tile <= 0x2B;
    case kBlockCastleDoor:
        return tile >= 0x2C && tile <= 0x2F;
    case kBlockThin:
        return tile == 0xFE;
    case kBlockLava:
        return tile == 0x20;
    case kBlockBridge:
        return tile == 0xBA;
    case kBlockAxe:
        return tile == 0xBB;
    case kBlockCloudTl:
    case kBlockCloudTr:
        return tile >= 0x35 && tile <= 0x36;
    case kBlockCloudT:
        return tile >= 0x39 && tile <= 0x3A;
    case kBlockCloudBl:
    case kBlockCloudBr:
        return tile >= 0x3D && tile <= 0x3E;
    case kBlockCloudB:
        return tile >= 0x41 && tile <= 0x42;
    case kBlockHillPeak:
        return tile >= 0x45 && tile <= 0x46;
    case kBlockHillSlopeL:
    case kBlockHillSlopeR:
        return tile >= 0x49 && tile <= 0x4A;
    case kBlockHillFill:
        return tile >= 0x4D && tile <= 0x4E;
    case kBlockBushL:
    case kBlockBushR:
        return tile >= 0x51 && tile <= 0x52;
    case kBlockBushM:
        return tile >= 0x55 && tile <= 0x56;
    case kBlockSpent:
        return tile >= kTileSpentLo && tile <= kTileSpentHi;
    case kBlockCoin:
        return tile >= kTileWorldCoinLo && tile <= kTileWorldCoinHi;
    default:
        return false;
    }
}

// every family a terrain cell may legitimately render as: the pinned 0xa0-0xbf block, the eight
// ids past mario's frames, and the scenery run inside what is otherwise the font's own range
bool is_known_terrain_family(uint8_t tile) {
    return tile <= 0x5F || (tile >= 0xA0 && tile <= 0xBF) || tile >= 0xF8;
}

